style.css:
@-moz-document domain("web.stremio.com") {
/* Core dark theme */
  body, html, .app-container {
    background-color: #0d0d0d !important;
    color: #e6e6e6 !important;
    font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif !important;
  }

  /* Remove hover effects */
  *:hover {
    background-color: inherit !important;
    color: inherit !important;
    box-shadow: none !important;
    transform: none !important;
    border-color: inherit !important;
  }

  /* Hide sidebar completely */
  .side-bar, .menu-bar, .sidebar, .sidebar-container {
    display: none !important;
    width: 0 !important;
    visibility: hidden !important;
  }

  /* Adjust main content layout after sidebar removal */
  .main-content, .app-content, .content-area {
    margin-left: 0 !important;
    width: 100% !important;
  }

  /* Red gradient buttons */
  .button, .btn, .button-main, .action-button {
    background: linear-gradient(135deg, #ff1a1a, #cc0000) !important;
    color: #fff !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* Remove hover styles from buttons */
  .button:hover, .btn:hover, .action-button:hover {
    background: linear-gradient(135deg, #ff1a1a, #cc0000) !important;
    color: #fff !important;
  }

  /* Tiles, posters, cards */
  .poster-item, .media-item, .addon-card, .card {
    background-color: #1a1a1a !important;
    border: 1px solid #2a2a2a !important;
    box-shadow: none !important;
  }

  /* Hide any promotional or unnecessary UI elements */
  .ad-banner, .footer, .promo, .help-section, .newsletter, .extra-info {
    display: none !important;
  }

  /* Links */
  a, .link {
    color: #ff4d4d !important;
    text-decoration: none !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 8px;
    background-color: #111;
  }
  ::-webkit-scrollbar-thumb {
    background-color: #333;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background-color: #444;
  }
}
